const item = $input.item.json;
const payload = item.data ?? item.body?.data ?? item.body ?? item;
const parsed = item._parsed ?? payload._parsed ?? {};

// Determina se a mensagem veio de mim.
// Mensagens fromMe podem ser da IA ou do operador humano. Nunca trate
// qualquer fromMe como intervenção: o operador usa #humano ou #retomar.
const fromMe = parsed?.fromMe ?? payload?.key?.fromMe ?? false;

// Determina se é grupo (bloqueia por padrão)
const isGroup = parsed?.isGroup || false;
if (isGroup === true) {
  return null;
}

// Extrai remetente (prioridade para remoteJidAlt, que é o número limpo)
const remetente = payload?.key?.remoteJidAlt ||
                  payload?.key?.remoteJid ||
                  parsed?.from ||
                  "";

// Inicializa variáveis
let texto = "";
let messageType = "unknown";
let mediaUrl = null;
let mediaMimeType = null;
let mediaCaption = null;
let mediaKey = null;
let mediaKeyType = null;
let fileEncSha256 = null;
let fileSha256 = null;
let directPath = null;
let fileName = null;
let fileLength = null;
let height = null;
let width = null;
let latitude = null;
let longitude = null;
let mediaBase64 = null;

// NOVAS VARIÁVEIS PARA BOTÕES
let buttonId = null;
let buttonText = null;
let buttonIndex = null;

const msg = payload?.message || {};
const media = item.media || {};
const fallbackName = (prefix, ext) => `${prefix}_${payload?.key?.id || Date.now()}.${ext}`;

// ===== TEXTO SIMPLES =====
if (msg.conversation) {
  texto = msg.conversation;
  messageType = "conversation";
}

// ===== TEXTO EXTENDIDO =====
else if (msg.extendedTextMessage?.text) {
  texto = msg.extendedTextMessage.text;
  messageType = "extended_text";
}

// ===== BOTÃO TEMPLATE =====
else if (msg.templateButtonReplyMessage) {
  messageType = "button_reply";
  texto = msg.templateButtonReplyMessage.selectedDisplayText || "";
  buttonId = msg.templateButtonReplyMessage.selectedId || null;
  buttonText = msg.templateButtonReplyMessage.selectedDisplayText || null;
  buttonIndex = msg.templateButtonReplyMessage.selectedIndex ?? null;
}

// ===== BOTÃO INTERATIVO =====
else if (msg.buttonsResponseMessage) {
  messageType = "button_reply";
  texto = msg.buttonsResponseMessage.selectedDisplayText || "";
  buttonId = msg.buttonsResponseMessage.selectedButtonId || null;
  buttonText = msg.buttonsResponseMessage.selectedDisplayText || null;
}

// ===== LIST RESPONSE =====
else if (msg.listResponseMessage) {
  messageType = "list_reply";
  texto = msg.listResponseMessage.title || "";
  buttonId = msg.listResponseMessage.singleSelectReply?.selectedRowId || null;
  buttonText = msg.listResponseMessage.title || null;
}

// ===== IMAGEM =====
else if (msg.imageMessage) {
  messageType = "image";
  mediaUrl = msg.imageMessage.url;
  mediaMimeType = msg.imageMessage.mimetype;
  mediaCaption = msg.imageMessage.caption || "";
  texto = mediaCaption;
  mediaKey = msg.imageMessage.mediaKey;
  mediaKeyType = msg.imageMessage.mediaKeyType;
  fileEncSha256 = msg.imageMessage.fileEncSha256;
  fileSha256 = msg.imageMessage.fileSha256;
  directPath = msg.imageMessage.directPath;
  fileName = msg.imageMessage.fileName || media.filename || fallbackName("image", "jpg");
  fileLength = msg.imageMessage.fileLength;
  height = msg.imageMessage.height;
  width = msg.imageMessage.width;
  mediaBase64 = media.base64 || null;
}

// ===== ÁUDIO =====
else if (msg.audioMessage) {
  messageType = "audio";
  mediaUrl = msg.audioMessage.url;
  mediaMimeType = msg.audioMessage.mimetype;
  texto = "";
  mediaKey = msg.audioMessage.mediaKey;
  mediaKeyType = msg.audioMessage.mediaKeyType;
  fileEncSha256 = msg.audioMessage.fileEncSha256;
  fileSha256 = msg.audioMessage.fileSha256;
  directPath = msg.audioMessage.directPath;
  fileName = msg.audioMessage.fileName || media.filename || fallbackName("audio", "ogg");
  fileLength = msg.audioMessage.fileLength;
  mediaBase64 = media.base64 || null;
}

// ===== VÍDEO =====
else if (msg.videoMessage) {
  messageType = "video";
  mediaUrl = msg.videoMessage.url;
  mediaMimeType = msg.videoMessage.mimetype;
  mediaCaption = msg.videoMessage.caption || "";
  texto = mediaCaption;
  mediaKey = msg.videoMessage.mediaKey;
  mediaKeyType = msg.videoMessage.mediaKeyType;
  fileEncSha256 = msg.videoMessage.fileEncSha256;
  fileSha256 = msg.videoMessage.fileSha256;
  directPath = msg.videoMessage.directPath;
  fileName = msg.videoMessage.fileName || media.filename || fallbackName("video", "mp4");
  fileLength = msg.videoMessage.fileLength;
  height = msg.videoMessage.height;
  width = msg.videoMessage.width;
  mediaBase64 = media.base64 || null;
}

// ===== DOCUMENTO =====
else if (msg.documentMessage) {
  messageType = "document";
  mediaUrl = msg.documentMessage.url;
  mediaMimeType = msg.documentMessage.mimetype;
  mediaCaption = msg.documentMessage.caption || "";
  texto = mediaCaption;
  mediaKey = msg.documentMessage.mediaKey;
  mediaKeyType = msg.documentMessage.mediaKeyType;
  fileEncSha256 = msg.documentMessage.fileEncSha256;
  fileSha256 = msg.documentMessage.fileSha256;
  directPath = msg.documentMessage.directPath;
  fileName = msg.documentMessage.fileName || media.filename || fallbackName("document", "pdf");
  fileLength = msg.documentMessage.fileLength;
  mediaBase64 = media.base64 || null;
}

// ===== STICKER =====
else if (msg.stickerMessage) {
  messageType = "sticker";
  mediaUrl = msg.stickerMessage.url;
  mediaMimeType = msg.stickerMessage.mimetype;
  texto = "";
  mediaKey = msg.stickerMessage.mediaKey;
  mediaKeyType = msg.stickerMessage.mediaKeyType;
  fileEncSha256 = msg.stickerMessage.fileEncSha256;
  fileSha256 = msg.stickerMessage.fileSha256;
  directPath = msg.stickerMessage.directPath;
  fileName = msg.stickerMessage.fileName || media.filename || fallbackName("sticker", "webp");
  fileLength = msg.stickerMessage.fileLength;
  height = msg.stickerMessage.height;
  width = msg.stickerMessage.width;
  mediaBase64 = media.base64 || null;
}

// ===== LOCALIZAÇÃO =====
else if (msg.locationMessage) {
  messageType = "location";
  latitude = msg.locationMessage.degreesLatitude;
  longitude = msg.locationMessage.degreesLongitude;
  texto = `${latitude},${longitude}`;
}

// Fallback
if (!texto && parsed?.text) {
  texto = item._parsed.text;
  messageType = item._parsed.messageType || messageType;
}

// ===== ÁREA CTWA =====
const contextInfo =
  msg.extendedTextMessage?.contextInfo ||
  msg.imageMessage?.contextInfo ||
  msg.videoMessage?.contextInfo ||
  msg.documentMessage?.contextInfo ||
  msg.conversation?.contextInfo ||
  null;

const adReply = contextInfo?.externalAdReplyInfo || null;

const ctwa = {
  isAd: !!adReply,
  sourceType: adReply?.sourceType || null,
  sourceId: adReply?.sourceId || null,
  sourceUrl: adReply?.sourceUrl || null,
  title: adReply?.title || null,
  body: adReply?.body || null,
  mediaType: adReply?.mediaType || null,
  thumbnailUrl: adReply?.thumbnailUrl || null,
  ctwaClid: contextInfo?.ctwaClid || adReply?.ctwaClid || null,
};

// Metadados
const pushName = payload?.pushName || parsed?.pushName || "";
const messageId = payload?.key?.id || parsed?.messageId || "";
const instanceId = (item.instanceId ?? payload.instanceId) || item._meta?.instanceId || "";
const timestamp = payload?.messageTimestamp || parsed?.timestamp || Date.now();
const participant = payload?.key?.participant || parsed?.participant || "";

// Controle humano persistente por comando explícito.
// A API WhatsApp marca tanto a IA quanto o operador como fromMe; sem um
// comando não existe forma confiável de distinguir os dois eventos.
const textoControle = String(texto || '').trim();
const humanTakeover = fromMe && /^(#humano|#assumir|#pausar)\b/i.test(textoControle);
const humanResume = fromMe && /^(#retomar|#bot|#voltar)\b/i.test(textoControle);
const eventKind = humanTakeover ? 'human_takeover' : humanResume ? 'human_resume' : fromMe ? 'bot_outgoing_ignored' : 'lead_message';

// Retorno final com todos os campos
return {
  eventKind,
  humanTakeover,
  humanResume,
  remetente,
  texto,
  pushName,
  messageType,
  messageId,
  instanceId,
  timestamp,
  isGroup,
  participant,
  mediaUrl,
  mediaMimeType,
  mediaCaption,
  mediaKey,
  mediaKeyType,
  fileEncSha256,
  fileSha256,
  directPath,
  fileName,
  fileLength,
  height,
  width,
  latitude,
  longitude,
  fromMe,
  remoteJidAlt: payload?.key?.remoteJidAlt || null,
  remoteJid: payload?.key?.remoteJid || null,
  mediaBase64,
  ctwa,
  buttonId,
  buttonText,
  buttonIndex,
};

const limpeza = $('Limpeza').item.json;
const tipo = limpeza.messageType;

const raw = $json;

// Helper: tenta extrair texto de todas as rotas possíveis do Gemini
function extrairTexto(resp) {
  if (!resp) return "";

  // Se vier array (formato antigo), pega o primeiro
  const r = Array.isArray(resp) ? resp[0] : resp;
  if (!r) return "";

  const partes = r?.content?.parts || r?.candidates?.[0]?.content?.parts || [];

  for (const parte of partes) {
    // Áudio transcrito
    if (parte?.audioTranscription?.text) return parte.audioTranscription.text;
    // Texto normal (imagem, doc, etc)
    if (parte?.text) return parte.text;
  }

  // Rotas antigas como último recurso
  return (
    r?.text ||
    r?.candidates?.[0]?.content?.parts?.[0]?.text ||
    r?.content?.parts?.[0]?.text ||
    ""
  );
}

let textoFinal = limpeza.texto || "";

if (tipo === 'audio') {
  const transcrito = extrairTexto(raw);
  textoFinal = transcrito || "[áudio recebido, não consegui transcrever]";
}

if (tipo === 'image') {
  const descricaoImagem = extrairTexto(raw);
  textoFinal = limpeza.mediaCaption
    ? `${limpeza.mediaCaption} [imagem: ${descricaoImagem}]`
    : `[imagem enviada: ${descricaoImagem}]`;
}

if (tipo === 'document') {
  const descricaoDoc = extrairTexto(raw);
  textoFinal = limpeza.mediaCaption
    ? `${limpeza.mediaCaption} [documento: ${descricaoDoc}]`
    : `[documento enviado: ${descricaoDoc}]`;
}

return {
  json: {
    ...limpeza,
    texto: textoFinal
  }
};

// NÓ: Preparar pra IA — versão completa com agenda automática
// Modo: Run Once for Each Item
// Coloque este node antes do AI Agent.
// Preserva os dados do Limpeza e do Debounce e acrescenta as datas da agenda.

const entradaDebounce = $json || {};

// O Debounce pode remover o pareamento original. first() é seguro aqui porque
// cada execução trata uma mensagem por vez.
let dadosLimpeza = {};
try {
  dadosLimpeza = $('Limpeza').first()?.json || {};
} catch (e) {
  dadosLimpeza = {};
}

// O dado produzido pelo Debounce tem prioridade sobre o Limpeza.
const entrada = {
  ...dadosLimpeza,
  ...entradaDebounce,
};

function textoSeguro(valor) {
  if (valor === null || valor === undefined) return '';
  if (typeof valor === 'string') return valor.trim();
  if (typeof valor === 'number' || typeof valor === 'boolean') return String(valor);
  return '';
}

function primeiroTexto(...valores) {
  for (const valor of valores) {
    const texto = textoSeguro(valor);
    if (texto) return texto;
  }
  return '';
}

function dataISO(momento) {
  return momento.setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd');
}

const agora = $now.setZone('America/Sao_Paulo');

// Mensagem real do lead. Não misture datas, instruções ou contexto neste campo.
const texto = primeiroTexto(
  entradaDebounce.texto,
  dadosLimpeza.texto,
  entradaDebounce.fullMessage,
  dadosLimpeza.fullMessage,
  entradaDebounce.body,
  dadosLimpeza.body,
  entradaDebounce.message,
  dadosLimpeza.message
);

// Campos principais normalizados.
const telefone = primeiroTexto(
  entradaDebounce.telefone,
  dadosLimpeza.telefone,
  entradaDebounce.phone,
  dadosLimpeza.phone,
  entradaDebounce.remoteJidAlt,
  dadosLimpeza.remoteJidAlt,
  entradaDebounce.remoteJid,
  dadosLimpeza.remoteJid,
  entradaDebounce.remetente,
  dadosLimpeza.remetente
);

const remetente = primeiroTexto(
  entradaDebounce.remetente,
  dadosLimpeza.remetente,
  entradaDebounce.telefone,
  dadosLimpeza.telefone,
  entradaDebounce.remoteJidAlt,
  dadosLimpeza.remoteJidAlt
);

const remoteJid = primeiroTexto(
  entradaDebounce.remoteJid,
  dadosLimpeza.remoteJid,
  entradaDebounce.remoteJidAlt,
  dadosLimpeza.remoteJidAlt,
  telefone
);

const nome = primeiroTexto(
  entradaDebounce.nome,
  dadosLimpeza.nome,
  entradaDebounce.pushName,
  dadosLimpeza.pushName
);

const messageType = primeiroTexto(
  entradaDebounce.messageType,
  dadosLimpeza.messageType,
  entradaDebounce.tipo,
  dadosLimpeza.tipo
);

const sessionId = primeiroTexto(
  entradaDebounce.sessionId,
  dadosLimpeza.sessionId,
  entradaDebounce.remoteJidAlt,
  dadosLimpeza.remoteJidAlt,
  remoteJid,
  telefone
);

// Datas relativas gerais, preservadas para compatibilidade com o prompt/fluxo.
function proximaOcorrencia(diaAlvo) {
  // Luxon: segunda=1 ... domingo=7.
  // Conversão para domingo=0 ... sábado=6.
  const diaAtual = agora.weekday % 7;
  let diferenca = (diaAlvo - diaAtual + 7) % 7;
  if (diferenca === 0) diferenca = 7;
  return dataISO(agora.plus({ days: diferenca }));
}

const diasSemana = [
  'domingo',
  'segunda',
  'terça',
  'quarta',
  'quinta',
  'sexta',
  'sábado',
];

const datasResolvidas = {
  hoje: dataISO(agora),
  hoje_dia_semana: diasSemana[agora.weekday % 7],
  amanha: dataISO(agora.plus({ days: 1 })),
  depois_de_amanha: dataISO(agora.plus({ days: 2 })),
  proxima_segunda: proximaOcorrencia(1),
  proxima_terca: proximaOcorrencia(2),
  proxima_quarta: proximaOcorrencia(3),
  proxima_quinta: proximaOcorrencia(4),
  proxima_sexta: proximaOcorrencia(5),
  proximo_sabado: proximaOcorrencia(6),
  proximo_domingo: proximaOcorrencia(0),
};

// Datas específicas da consulta automática da agenda.
// O fluxo solicitado usa 3 dias corridos para reproduzir:
// 19/09/2026 -> 22/09/2026.
const dataAtualSistema = dataISO(agora);
const dataAgendaInicial = dataISO(agora.plus({ days: 3 }));
const dataAgendaAlternativa1 = dataISO(agora.plus({ days: 4 }));
const dataAgendaAlternativa2 = dataISO(agora.plus({ days: 5 }));

const contextoDatasSistema = [
  'CONTEXTO INTERNO DE DATAS — NÃO MOSTRAR AO LEAD',
  'Fuso: America/Sao_Paulo',
  'Data atual: ' + dataAtualSistema,
  'Primeira data da agenda: ' + dataAgendaInicial,
  'Alternativa 1 da agenda: ' + dataAgendaAlternativa1,
  'Alternativa 2 da agenda: ' + dataAgendaAlternativa2,
  'Amanhã: ' + datasResolvidas.amanha,
  'Depois de amanhã: ' + datasResolvidas.depois_de_amanha,
  'Use os valores ISO prontos ao chamar consultar_horarios.',
  'Nunca use datas de exemplos, memória, histórico, pinData ou chamadas anteriores.',
  'FIM DO CONTEXTO INTERNO DE DATAS',
].join('\n');

return {
  json: {
    // Preserva todos os campos do Limpeza e do Debounce.
    ...dadosLimpeza,
    ...entradaDebounce,

    // Campos normalizados usados pelo Agent, memória, PAPI e Chat Memory.
    telefone,
    remetente,
    remoteJid,
    remoteJidAlt: entrada.remoteJidAlt || remoteJid,
    nome,
    pushName: entrada.pushName || dadosLimpeza.pushName || '',
    messageType,
    tipo: entrada.tipo || messageType,
    sessionId,

    // Somente a mensagem real do lead deve ir para o campo Text do AI Agent.
    texto,

    // Compatibilidade com o fluxo atual.
    quantidadeMensagensAgrupadas:
      entrada.messageCount || entrada.quantidadeMensagensAgrupadas || 1,

    // Datas gerais já existentes no fluxo.
    datasResolvidas,
    contextoDatasSistema,
    dataAtual: dataAtualSistema,
    fusoHorario: 'America/Sao_Paulo',

    // Campos novos exigidos pelo prompt de agenda automática.
    dataAtualSistema,
    dataAgendaInicial,
    dataAgendaAlternativa1,
    dataAgendaAlternativa2,
    serviceIdAgenda: '2',
    providerIdAgenda: '2',
    servicoAgenda: 'Call de apresentação',
    profissionalAgenda: 'Rafael Tourino',
    contextoAgenda: {
      dataAtual: dataAtualSistema,
      primeiraData: dataAgendaInicial,
      alternativas: [dataAgendaAlternativa1, dataAgendaAlternativa2],
      serviceId: '2',
      providerId: '2',
      servico: 'Call de apresentação',
      profissional: 'Rafael Tourino',
    },
  },
};

// PREPARAR ENVIO — versão mínima para o payload atual do AI Agent
function jsonDo(nome) {
  try { return $(nome).first()?.json || {}; } catch { return {}; }
}

function parse(v) {
  if (typeof v !== 'string') return v;
  const s = v.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
  try { return JSON.parse(s); } catch { return v; }
}

const limpeza = jsonDo('Limpeza');
const entrada = $input.first()?.json || {};
const output = parse(entrada.output ?? entrada.response ?? entrada.text ?? entrada);
const resposta = parse(output);
const mensagens = Array.isArray(resposta?.mensagens)
  ? resposta.mensagens
  : [{ tipo: 'text', content: String(resposta ?? '') }];

const base = {
  remetente: limpeza.remetente || entrada.remetente,
  pushName: limpeza.pushName || entrada.pushName || '',
  instanceId: limpeza.instanceId || entrada.instanceId,
  remoteJidAlt: limpeza.remoteJidAlt || entrada.remoteJidAlt,
  textoLead: limpeza.texto || entrada.textoLead || '',
  ctwa: limpeza.ctwa || entrada.ctwa || null,
  timestamp: limpeza.timestamp || entrada.timestamp || Date.now(),
  inboundMessageId: limpeza.messageId || entrada.messageId || '',
  _isRedisItem: false,
};

const resultado = [];
let outboundIndex = 0;
for (const mensagem of mensagens) {
  const tipo = String(mensagem?.tipo || mensagem?.type || 'text').toLowerCase();
  const content = String(mensagem?.content ?? mensagem?.text ?? '').trim();
  if (!content) continue;

  // Divide uma mensagem longa em blocos separados por linha em branco.
  const partes = tipo === 'text'
    ? content.split(/\n\s*\n+/).map(x => x.trim()).filter(Boolean)
    : [content];

  for (const parte of partes) {
    const item = { ...base, type: tipo === 'audio' ? 'audio' : tipo === 'button' ? 'button' : 'text', content: parte, outboundIndex: outboundIndex++ };
    if (item.type === 'button') {
      item.buttons = (mensagem.buttons || mensagem.botoes || []).map(b => ({
        id: String(b.id || b.buttonId || b.displayText || '').trim(),
        displayText: String(b.displayText || b.text || b.label || b.id || '').trim(),
      })).filter(b => b.id && b.displayText).slice(0, 3);
      if (!item.buttons.length) { item.type = 'text'; delete item.buttons; }
    }
    resultado.push({ json: item });
  }
}

return resultado.length ? resultado : [{ json: { ...base, type: 'text', content: 'Não consegui preparar a resposta. Tente novamente.' } }];

