={{ (() => { const raw = $json.timestamp; const n = Number(raw); const receivedAt = Number.isFinite(n) && n > 0 ? new Date(n * (n < 1e12 ? 1000 : 1)).toISOString() : new Date(raw || Date.now()).toISOString(); const fallbackId = [raw || '', $json.remetente || '', $itemIndex].join(':') || $execution.id; const metadata = Object.fromEntries(Object.entries({ instanceId: $json.instanceId, mediaUrl: $json.mediaUrl, mediaMimeType: $json.mediaMimeType, fileName: $json.fileName, fileLength: Number($json.fileLength) || undefined, buttonId: $json.buttonId, buttonText: $json.buttonText, isGroup: $json.isGroup }).filter(([, value]) => value !== null && value !== undefined && value !== '')); return JSON.stringify({
  eventId: (String($json.instanceId || 'papi').slice(0,40) + ':' + String($json.messageId || fallbackId)).slice(0,180),
  name: String($json.pushName || '').trim() || undefined,
  phone: String($json.remetente || '').replace(/\D/g, ''),
  content: String($json.texto || $json.mediaCaption || $json.buttonText || ($json.messageType === 'audio' ? '[Áudio recebido]' : $json.messageType === 'image' ? '[Imagem recebida]' : $json.messageType === 'video' ? '[Vídeo recebido]' : $json.messageType === 'document' ? '[Documento recebido]' : '[Mensagem recebida]')),
  messageType: ['text','image','audio','video','document'].includes($json.messageType) ? $json.messageType : 'text',
  receivedAt,
  metadata
}); })() }}
